"""Explicit immutable node bundle; never replaces the e57 load artifact or deploys."""
from pathlib import Path
import argparse
import hashlib
import io
import json
import shutil
import tarfile
import zipfile
import common as p


def entries(data):
    with zipfile.ZipFile(io.BytesIO(data)) as jar:
        names = jar.namelist(); p.require(len(names) == len(set(names)), 'Duplicate JAR entry')
        return {name: hashlib.sha256(jar.read(name)).hexdigest() for name in names if not name.endswith('/')}


def bundle():
    info = p.read(p.BASE / 'build.json'); revision = info['revision']
    tests = p.read(p.OUT / 'tool-validation/java-tests.json')
    p.require(tests['revision'] == revision and tests['exitCode'] == 0 and tests['failures'] == tests['skipped'] == 0
              and tests['tests'] > 0 and tests['sourceArchiveSha256'] == info['sourceArchiveSha256'], 'Isolated node build not fully green')
    p.require(p.digest(info['sourceArchivePath']) == info['sourceArchiveSha256'], 'Committed build source archive changed')
    build = Path(info['root']); p.require(build.parent == p.BASE and build.name == 'build-' + revision, 'Unexpected isolated build root')
    prior = p.artifact_prerequisites(); load = prior['loadIdentity']; c = p.capacity_module().frozen_parent()
    c.archive_manifest(load)
    stage = p.BASE / ('node-' + revision); archive_path = p.BASE / ('node-' + revision + '.tar.gz')
    for path in [stage, archive_path, p.BASE / 'node-release.json', p.OUT / 'node-release.json', p.OUT / 'node-deployment-manifest.json']:
        p.require(not path.exists(), 'Existing immutable bundle/release; do not overwrite: ' + str(path))
    old = {}
    with tarfile.open(load['archive']) as archive:
        for member in archive.getmembers():
            if member.isfile() and member.name.startswith('dist/cluster/lib/') and member.name.endswith('.jar'):
                old[Path(member.name).name] = entries(archive.extractfile(member).read())
    new_lib = build / 'cluster/build/install/cluster/lib'
    new = {path.name: entries(path.read_bytes()) for path in new_lib.glob('*.jar')}
    p.require(old and set(new) == set(old), 'JAR filename set differs from e57 load')
    allowed = lambda name: name == 'io/vectormatch/cluster/ClusterNodeMain.class' or name.startswith('io/vectormatch/cluster/ClusterNodeMain$')
    changed, unchanged = [], {}
    for name in sorted(new):
        if not name.startswith('cluster-'):
            p.require(new[name] == old[name], 'Unrelated core/dependency JAR entries changed: ' + name)
        else:
            for entry in sorted(set(new[name]) | set(old[name])):
                if new[name].get(entry) == old[name].get(entry):
                    unchanged[entry] = new[name][entry]
                else:
                    p.require(allowed(entry), 'Unexpected cluster entry changed: ' + entry); changed.append(entry)
    p.require(changed, 'No new NodeMain idle bytecode')
    lib = stage / 'dist/cluster/lib'; lib.mkdir(parents=True)
    for path in sorted(new_lib.glob('*.jar')): shutil.copyfile(path, lib / path.name)
    for name in ('deploy/remote_service.py', 'deploy/test_remote_service.py',
                 'scripts/capacity-telemetry.py', 'scripts/tests/test_capacity_telemetry.py'):
        target = stage / name; target.parent.mkdir(parents=True, exist_ok=True); shutil.copyfile(build / name, target)
    files = {str(path.relative_to(stage)): p.digest(path) for path in stage.rglob('*') if path.is_file()}
    manifest = {'revision': revision, 'role': 'capacity-node-only-data-path-idle-control',
                'comparedAgainstNodeRevision': p.LOAD_REVISION, 'changedClusterEntries': sorted(changed),
                'unchangedClusterEntriesSha256': unchanged, 'files': files, 'sourceArchiveSha256': info['sourceArchiveSha256'],
                'fixedLoadRevision': p.LOAD_REVISION, 'fixedLoadBundleSha256': p.LOAD_BUNDLE,
                'scope': 'New NODE-only artifact, A/B same bytes. Every JAR entry compared with fixed e57; only NodeMain/nested classes may differ. Core/client/other cluster/dependency entries identical; ZIP timestamps excluded. Separate e57 multiplexed load is unchanged.'}
    p.save_new(stage / 'DEPLOYMENT.json', manifest)
    with tarfile.open(archive_path, 'w:gz') as archive:
        for path in sorted(stage.iterdir()): archive.add(path, arcname=path.name, recursive=True)
    release = {'revision': revision, 'root': '/opt/vectormatch/optimization-node-releases/' + revision,
               'archive': str(archive_path), 'bundleSha256': p.digest(archive_path), 'archiveBytes': archive_path.stat().st_size}
    c.archive_manifest(release)
    actual = p.node_class_diff(c, release, load)
    p.require(actual['changedClusterEntries'] == sorted(changed), 'Packaged class comparison differs')
    p.save_new(p.BASE / 'node-release.json', release); p.save_new(p.OUT / 'node-release.json', release)
    p.save_new(p.OUT / 'node-deployment-manifest.json', manifest)
    print('IMMUTABLE_NODE_IDLE_BUNDLE_NO_DEPLOYMENT', json.dumps(release), flush=True)
    return release


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument('--execute', action='store_true'); args = parser.parse_args(argv)
    if not args.execute:
        print(json.dumps({'draftOnly': True, 'bundleOrDeploymentExecuted': False, 'fixedLoadRevision': p.LOAD_REVISION})); return
    bundle()


if __name__ == '__main__':
    main()
